// Deliberate presentation pacing. These stages do not represent live AI work.
let processingRun=null;
const loadingDialog=document.createElement('dialog');
loadingDialog.id='processing-dialog';loadingDialog.setAttribute('aria-labelledby','processing-title');document.body.append(loadingDialog);
function runProcessing(kind){if(processingRun)return Promise.resolve(false);return new Promise(resolve=>{const transcript=kind==='transcript';const stages=transcript?['Reading the call transcript','Identifying vendor details and services','Organizing packages, pricing, and policies','Checking conflicts and missing information','Preparing the profile for your review']:['Reading the vendor source packet','Identifying business details and services','Organizing packages, pricing, and policies','Checking conflicts and missing information','Preparing the profile for your review'];const run={timer:null,finish:null};processingRun=run;let step=0;loadingDialog.innerHTML=`<div class="processing-topline"><span class="eyebrow">${transcript?'TRANSCRIPT → PROFILE':'SOURCES → PROFILE'}</span><span class="processing-stage-count" id="processing-stage-count">01 / 05</span></div><h2 id="processing-title">${transcript?'Turning the conversation into a profile.':'Bringing the vendor details together.'}</h2><p class="processing-subtitle">${esc(samples[state.type].name)} · ${esc(state.type)}</p><div class="processing-layout"><div class="processing-visual" aria-hidden="true"><div class="processing-paper"><span>${transcript?'CALL TRANSCRIPT':'SOURCE PACKET'}</span><i></i><i></i><i></i><i></i><i></i><b>✧</b></div><div class="processing-result"><small>VENDOR PROFILE</small><strong>${esc(samples[state.type].name)}</strong><span>Business & contacts</span><span>Services & packages</span><span>Policies & follow-up</span></div></div><ol class="processing-stages">${stages.map((s,i)=>`<li data-processing-stage="${i}" class="${i===0?'current':''}"><span class="processing-number">${i+1}</span><span>${s}</span><b aria-hidden="true">${i===0?'…':''}</b></li>`).join('')}</ol></div><div class="processing-status" role="status" aria-live="polite" id="processing-status">${stages[0]}…</div><progress id="processing-progress" max="5" value="0" aria-label="Profile preparation progress"></progress><div class="processing-bottom"><small>Simulated demo sequence · about 7 seconds</small><button class="text-btn" id="cancel-processing">Cancel</button></div>`;
run.finish=success=>{if(processingRun!==run)return;clearTimeout(run.timer);processingRun=null;loadingDialog.oncancel=null;if(loadingDialog.open)loadingDialog.close();resolve(success)};
loadingDialog.oncancel=e=>{e.preventDefault();run.finish(false)};loadingDialog.querySelector('#cancel-processing').onclick=()=>run.finish(false);loadingDialog.showModal();
function advance(){if(processingRun!==run)return;loadingDialog.querySelector(`[data-processing-stage="${step}"]`).className='complete';loadingDialog.querySelector(`[data-processing-stage="${step}"] b`).textContent='✓';step++;loadingDialog.querySelector('#processing-progress').value=step;if(step===stages.length){loadingDialog.querySelector('#processing-status').textContent='Draft ready. Opening the review workspace…';run.timer=setTimeout(()=>run.finish(true),450);return}loadingDialog.querySelector(`[data-processing-stage="${step}"]`).className='current';loadingDialog.querySelector(`[data-processing-stage="${step}"] b`).textContent='…';loadingDialog.querySelector('#processing-status').textContent=stages[step]+'…';loadingDialog.querySelector('#processing-stage-count').textContent=String(step+1).padStart(2,'0')+' / 05';run.timer=setTimeout(advance,1250)}run.timer=setTimeout(advance,1250);
})}
const bindBeforeProcessing=bind;
bind=function(){bindBeforeProcessing();for(const [id,kind]of [['extract','sources'],['convert-transcript','transcript']]){const button=document.getElementById(id);if(!button)continue;const original=button.onclick;button.onclick=async()=>{if(processingRun)return;const valid=kind==='transcript'?state.transcript.trim().length>=20:state.tab==='transcript'?!!state.transcript.trim():/^https?:\/\/\S+\.\S+/.test(state.url);if(!valid){await original();return}button.disabled=true;try{const complete=await runProcessing(kind);if(complete)await original();else toast('Preparation cancelled. Your source input is still here.')}finally{button.disabled=false}}}};
render();
